-- DSH 桌面端本地 SQLite schema（内置 DDL，开机 CREATE TABLE IF NOT EXISTS 自建）
-- 自动从 local.db 导出;脱离远程 Vastbase 依赖。共 75 张表。
-- 重新生成: node scripts/gen_schema.mjs

CREATE TABLE IF NOT EXISTS "project_rules" ("id" TEXT PRIMARY KEY, "project_id" TEXT NOT NULL, "rule_type" TEXT NOT NULL, "content" TEXT NOT NULL DEFAULT '', "version" TEXT NOT NULL DEFAULT '1.0.0', "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, UNIQUE ("project_id", "rule_type"));
CREATE TABLE IF NOT EXISTS "agent_runs" ("id" TEXT, "session_id" TEXT, "project_id" TEXT, "user_id" TEXT, "turn_id" TEXT, "status" TEXT, "skill_name" TEXT, "mode" TEXT, "checkpoint_json" TEXT, "metadata_json" TEXT, "last_event_seq" INTEGER NOT NULL DEFAULT 0, "lease_owner" TEXT, "lease_expires_at" TEXT, "heartbeat_at" TEXT, "runner_pid" INTEGER, "recoverable" INTEGER NOT NULL DEFAULT 0, "retention_until" TEXT, "workspace_path" TEXT, "manifest_path" TEXT, "workspace_version" TEXT, "manifest_hash" TEXT, "environment_snapshot_path" TEXT, "environment_snapshot_version" TEXT, "environment_snapshot_hash" TEXT, "archived_at" TEXT, "archived_by" TEXT, "finished_at" TEXT, "viewed_at" TEXT, "status_changed_at" TEXT, "created_at" TEXT, "updated_at" TEXT, "deleted_at" TEXT, "deleted_by" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "agent_pending_inputs" ("id" TEXT, "run_id" TEXT, "session_id" TEXT, "project_id" TEXT, "user_id" TEXT, "request_id" TEXT UNIQUE, "input_type" TEXT, "status" TEXT, "payload_json" TEXT, "response_json" TEXT, "resume_handle_json" TEXT, "resume_expires_at" TEXT, "record_expires_at" TEXT, "responded_by" TEXT, "responded_at" TEXT, "created_at" TEXT, "updated_at" TEXT, "deleted_at" TEXT, "deleted_by" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "agent_run_events" ("id" TEXT PRIMARY KEY, "run_id" TEXT NOT NULL, "turn_id" TEXT, "call_id" TEXT, "seq" INTEGER NOT NULL, "event_type" TEXT NOT NULL, "status" TEXT, "input_summary" TEXT, "output_summary" TEXT, "artifact_id" TEXT, "error_code" TEXT, "retry_count" INTEGER NOT NULL DEFAULT 0, "metadata_json" TEXT, "created_at" TEXT NOT NULL, UNIQUE ("run_id", "seq"));
CREATE TABLE IF NOT EXISTS "agent_tool_calls" ("id" TEXT PRIMARY KEY, "run_id" TEXT NOT NULL, "turn_id" TEXT, "call_id" TEXT NOT NULL, "tool_name" TEXT NOT NULL, "access_mode" TEXT NOT NULL DEFAULT 'read', "status" TEXT NOT NULL DEFAULT 'pending', "attempt_count" INTEGER NOT NULL DEFAULT 0, "input_json" TEXT, "input_summary" TEXT, "result_json" TEXT, "output_summary" TEXT, "log_path" TEXT, "error_code" TEXT, "started_at" TEXT, "finished_at" TEXT, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, UNIQUE ("run_id", "call_id"));
CREATE TABLE IF NOT EXISTS "agent_subtask_runs" ("id" TEXT PRIMARY KEY, "run_id" TEXT NOT NULL UNIQUE, "parent_run_id" TEXT NOT NULL, "parent_call_id" TEXT, "call_id" TEXT NOT NULL, "query_execution_id" TEXT, "session_id" TEXT, "project_id" TEXT, "subtask_type" TEXT NOT NULL, "title" TEXT NOT NULL, "tool_name" TEXT, "tool_allowlist" TEXT NOT NULL, "read_only" INTEGER NOT NULL DEFAULT 1, "parallel_eligible" INTEGER NOT NULL DEFAULT 0, "parallel_group" TEXT, "status" TEXT NOT NULL, "input_snapshot" TEXT NOT NULL, "result_snapshot" TEXT, "evidence_refs" TEXT, "validation_refs" TEXT, "error_code" TEXT, "error_message" TEXT, "started_at" TEXT NOT NULL, "finished_at" TEXT, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "query_executions" ("id" TEXT PRIMARY KEY, "execution_key" TEXT NOT NULL UNIQUE, "version" TEXT NOT NULL, "parent_run_id" TEXT NOT NULL, "turn_id" TEXT NOT NULL, "session_id" TEXT, "project_id" TEXT, "user_id" TEXT, "root_question" TEXT, "last_delegated_question" TEXT, "preparation_context_mode" TEXT, "preparation_status" TEXT, "preparation_revision_id" TEXT, "preparation_revision" INTEGER, "status" TEXT NOT NULL DEFAULT 'running', "delegated_call_count" INTEGER NOT NULL DEFAULT 0, "error_code" TEXT, "error_message" TEXT, "finished_at" TEXT, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "project_data_preparation_revisions" ("id" TEXT PRIMARY KEY, "project_id" TEXT NOT NULL, "revision" INTEGER NOT NULL, "status" TEXT NOT NULL DEFAULT 'running', "coverage_summary_json" TEXT NOT NULL DEFAULT '{}', "failure_details_json" TEXT, "started_at" TEXT NOT NULL, "finished_at" TEXT, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, UNIQUE ("project_id", "revision"));
CREATE INDEX IF NOT EXISTS "idx_data_preparation_project_status_revision" ON "project_data_preparation_revisions" ("project_id", "status", "revision" DESC);
CREATE TABLE IF NOT EXISTS "agent_artifacts" ("id" TEXT PRIMARY KEY, "run_id" TEXT NOT NULL, "call_id" TEXT, "kind" TEXT NOT NULL, "path" TEXT, "mime_type" TEXT, "size_bytes" INTEGER, "sha256" TEXT, "metadata_json" TEXT, "created_at" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "project_artifacts" ("id" TEXT PRIMARY KEY, "project_id" TEXT NOT NULL, "source_locator" TEXT NOT NULL, "name" TEXT NOT NULL, "kind" TEXT NOT NULL DEFAULT 'file', "description" TEXT, "current_version_id" TEXT, "source_session_id" TEXT, "source_turn_id" TEXT, "source_run_id" TEXT, "source_item_id" TEXT, "source_tool_call_id" TEXT, "metadata_json" TEXT, "created_by" TEXT, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "deleted_at" TEXT, "deleted_by" TEXT);
CREATE TABLE IF NOT EXISTS "project_artifact_versions" ("id" TEXT PRIMARY KEY, "artifact_id" TEXT NOT NULL, "version_number" INTEGER NOT NULL, "snapshot_path" TEXT NOT NULL, "original_path" TEXT, "mime_type" TEXT, "size_bytes" INTEGER NOT NULL DEFAULT 0, "sha256" TEXT NOT NULL, "change_summary" TEXT, "source_session_id" TEXT, "source_turn_id" TEXT, "source_run_id" TEXT, "source_item_id" TEXT, "source_tool_call_id" TEXT, "restored_from_version_id" TEXT, "metadata_json" TEXT, "created_by" TEXT, "created_at" TEXT NOT NULL, UNIQUE ("artifact_id", "version_number"));
CREATE INDEX IF NOT EXISTS "idx_project_artifacts_project_updated" ON "project_artifacts" ("project_id", "updated_at" DESC) WHERE "deleted_at" IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "idx_project_artifacts_project_source" ON "project_artifacts" ("project_id", "source_locator") WHERE "project_id" <> '__chat__';
CREATE UNIQUE INDEX IF NOT EXISTS "idx_project_artifacts_chat_owner_source" ON "project_artifacts" ("created_by", "source_locator") WHERE "project_id" = '__chat__';
CREATE INDEX IF NOT EXISTS "idx_project_artifact_versions_artifact" ON "project_artifact_versions" ("artifact_id", "version_number" DESC);
CREATE TABLE IF NOT EXISTS "agent_canvases" ("id" TEXT PRIMARY KEY, "session_id" TEXT NOT NULL, "project_id" TEXT NOT NULL, "user_id" TEXT NOT NULL, "title" TEXT NOT NULL, "kind" TEXT NOT NULL DEFAULT 'document', "language" TEXT, "current_version_id" TEXT, "source_message_id" TEXT, "source_item_id" TEXT, "source_turn_id" TEXT, "source_run_id" TEXT, "metadata_json" TEXT, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "deleted_at" TEXT, "deleted_by" TEXT, UNIQUE ("session_id", "source_item_id"));
CREATE TABLE IF NOT EXISTS "agent_canvas_versions" ("id" TEXT PRIMARY KEY, "canvas_id" TEXT NOT NULL, "version_number" INTEGER NOT NULL, "snapshot_path" TEXT NOT NULL, "size_bytes" INTEGER NOT NULL DEFAULT 0, "sha256" TEXT NOT NULL, "change_summary" TEXT, "parent_version_id" TEXT, "restored_from_version_id" TEXT, "source_type" TEXT NOT NULL DEFAULT 'user', "source_turn_id" TEXT, "source_run_id" TEXT, "source_item_id" TEXT, "source_tool_call_id" TEXT, "metadata_json" TEXT, "created_by" TEXT, "created_at" TEXT NOT NULL, UNIQUE ("canvas_id", "version_number"));
CREATE TABLE IF NOT EXISTS "agent_canvas_suggestions" ("id" TEXT PRIMARY KEY, "canvas_id" TEXT NOT NULL, "base_version_id" TEXT NOT NULL, "start_offset" INTEGER NOT NULL, "end_offset" INTEGER NOT NULL, "selected_text" TEXT NOT NULL, "selected_text_hash" TEXT NOT NULL, "replacement_text" TEXT NOT NULL, "instruction" TEXT, "status" TEXT NOT NULL DEFAULT 'pending', "accepted_version_id" TEXT, "source_turn_id" TEXT, "source_run_id" TEXT, "source_item_id" TEXT, "source_tool_call_id" TEXT, "created_by" TEXT, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS "idx_agent_canvases_session_updated" ON "agent_canvases" ("session_id", "updated_at" DESC) WHERE "deleted_at" IS NULL;
CREATE INDEX IF NOT EXISTS "idx_agent_canvas_versions_canvas" ON "agent_canvas_versions" ("canvas_id", "version_number" DESC);
CREATE INDEX IF NOT EXISTS "idx_agent_canvas_suggestions_canvas" ON "agent_canvas_suggestions" ("canvas_id", "status", "created_at" DESC);
CREATE TABLE IF NOT EXISTS "agent_evidence_bundles" ("id" TEXT PRIMARY KEY, "run_id" TEXT NOT NULL, "turn_id" TEXT, "session_id" TEXT NOT NULL, "project_id" TEXT, "final_item_id" TEXT NOT NULL, "bundle_version" TEXT NOT NULL, "status" TEXT NOT NULL, "snapshot_hash" TEXT NOT NULL, "payload_json" TEXT NOT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "deleted_at" TEXT, "deleted_by" TEXT, UNIQUE ("run_id", "final_item_id"));
CREATE TABLE IF NOT EXISTS "agent_automations" ("id" TEXT PRIMARY KEY, "project_id" TEXT NOT NULL, "user_id" TEXT, "session_id" TEXT, "name" TEXT NOT NULL, "prompt" TEXT NOT NULL, "skill_name" TEXT, "model_id" TEXT, "model_name" TEXT, "reasoning_effort" TEXT, "allowed_tools_json" TEXT, "schedule_json" TEXT NOT NULL, "sandbox_policy_json" TEXT NOT NULL, "snapshot_policy_json" TEXT NOT NULL, "notification_policy_json" TEXT NOT NULL, "permission_policy_json" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'enabled', "next_run_at" TEXT, "last_run_at" TEXT, "last_status" TEXT, "consecutive_failures" INTEGER NOT NULL DEFAULT 0, "max_consecutive_failures" INTEGER NOT NULL DEFAULT 3, "lease_owner" TEXT, "lease_expires_at" TEXT, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "deleted_at" TEXT, "deleted_by" TEXT);
